import wrapt
from mock import patch

from ute_common_util.test.exception import NameExists


class Patcher(object):
    """Patcher is a special class created to simplify testing with mock.
    Patcher is able to store information about multiple libraries and patch them on-demand.

    **Add library to patcher**

    .. code-block:: python

        patcher = Patcher()
        patcher.add_to_patch('exists', 'os.path.exists')

    **Enable/Disable patch for all configured libraries**

    .. code-block:: python

        patcher.patch_all()
        patcher.stop_all_patches()

    **Enable/Disable patch for single library**

    .. code-block:: python

        patcher.patch('exists')
        patcher.stop_patch('exists')

    **Access to any library mock is via patcher arguments**

    .. code-block:: python

        patcher.patch('exists')
        patcher.exists.assert_has_calls(call().split('\\n'))

    **Most used scenario**

    .. code-block:: python

        patcher = Patcher()
        patcher.add_to_patch('exists', 'os.path.exists')
        patcher.add_to_patch('walk', 'os.walk')

        class TestClass(unittest.TestCase):
            setUp(self):
                patcher.patch_all()

            tearDown(self):
                patcher.stop_all_patches()
    """
    def __init__(self):
        self._patchers = {}
        self._mocks = {}

    def add_to_patch(self, name, patch_path, **kwargs):
        """Add library to patcher."""
        if name in self._patchers:
            raise NameExists("It is not possible to replace existing patcher")
        self._patchers[name] = patch(patch_path, **kwargs)

    def patch(self, *names):
        """Patch specified libraries."""
        for name in names:
            if name not in self._mocks:
                self._mocks[name] = self._patchers[name].start()

    def patch_all(self):
        """Patch all added libraries."""
        for name in self._patchers.keys():
            self._mocks[name] = self._patchers[name].start()

    def stop_patch(self, *names):
        """Stop patch for specified library."""
        for name in names:
            if name in self._mocks:
                self._patchers[name].stop()
                del self._mocks[name]

    def stop_all_patches(self):
        """Stop all working patches."""
        for name in self._mocks.keys():
            self._patchers[name].stop()
        self._mocks = {}

    def __getattr__(self, item):
        if item in self._mocks:
            return self._mocks[item]
        return self.__dict__[item]


class Patch(object):
    def __init__(self, patcher, *names):
        self._patcher = patcher
        self._names = names

    @wrapt.decorator
    def __call__(self, wrapped, instance, args, kwargs):
        self._patcher.patch(*self._names)
        try:
            return wrapped(*args, **kwargs)
        finally:
            self._patcher.stop_patch(*self._names)


class PatchAll(object):
    def __init__(self, patcher):
        self._patcher = patcher

    @wrapt.decorator
    def __call__(self, wrapped, instance, args, kwargs):
        self._patcher.patch_all()
        try:
            return wrapped(*args, **kwargs)
        finally:
            self._patcher.stop_all_patches()
